-- ============================================================================
-- v1542 — Plan list tables (owner decision 2026-11-21: plan lists are kept as rows in tables, not JSON)
-- ============================================================================
-- Key risks, quality gates and budget breakdown (project + stage plans), stage dependencies and stage
-- resource allocation move from JSONB columns on project_plans / stage_plans to their own tables.
-- The forms edit them as tables (PlanListTable); the plan services write these tables.
-- Generated by scripts/generate-plan-list-tables-sql.mjs from PLAN_LISTS — edit that config, not this file.
--
-- Access mirrors the parent plan (SQL v206): read when the plan is visible to you; change only when you could
-- edit the plan (PMO / System Admin unless baselined; otherwise author, owner or creator with owner/admin
-- project access while the plan is draft or under review). SECURITY DEFINER helpers with row_security off
-- avoid the RLS-join HTTP 500 class of bug.
--
-- Existing JSON values are copied once (arrays of objects, arrays of text, { key: value } maps). The old JSON
-- columns are left in place and no longer written; drop them later once the copy is confirmed.
-- Idempotent. Prerequisites: v205 / v206 (plan tables). After running: re-run SQL/v1251_planner_table_wall.sql.
-- ============================================================================

-- Helpers: read a value from a legacy JSON element.
CREATE OR REPLACE FUNCTION public.plan_list_pick(p_val JSONB, p_keys TEXT[])
RETURNS TEXT LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN jsonb_typeof(p_val) = 'object' THEN (
    SELECT NULLIF(btrim(p_val ->> k), '') FROM unnest(p_keys) WITH ORDINALITY AS u(k, n)
    WHERE NULLIF(btrim(p_val ->> k), '') IS NOT NULL ORDER BY n LIMIT 1) END
$$;
CREATE OR REPLACE FUNCTION public.plan_list_scalar(p_val JSONB)
RETURNS TEXT LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN jsonb_typeof(p_val) IN ('string', 'number', 'boolean') THEN NULLIF(btrim(p_val #>> '{}'), '') END
$$;
CREATE OR REPLACE FUNCTION public.plan_list_numeric(p_text TEXT)
RETURNS NUMERIC LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN regexp_replace(coalesce(p_text, ''), '[,\s]', '', 'g') ~ '^-?[0-9]+(\.[0-9]+)?$'
    THEN regexp_replace(p_text, '[,\s]', '', 'g')::NUMERIC END
$$;

-- Who may read / change the lists of a project plan.
CREATE OR REPLACE FUNCTION public.auth_user_can_view_project_plan(p_plan_id UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public SET row_security = off AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.project_plans pl
    WHERE pl.id = p_plan_id AND pl.is_deleted = FALSE
      AND (
        EXISTS (SELECT 1 FROM public.user_projects up JOIN public.users u ON up.user_id = u.id
                WHERE u.auth_user_id = auth.uid() AND up.project_id = pl.project_id AND up.is_deleted = FALSE)
        OR EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.roles r ON ur.role_id = r.id JOIN public.users u ON ur.user_id = u.id
                   WHERE u.auth_user_id = auth.uid() AND r.role_name IN ('pmo_admin', 'System Admin')
                     AND ur.is_active = TRUE AND ur.is_deleted = FALSE)
      )
  )
$$;
CREATE OR REPLACE FUNCTION public.auth_user_can_edit_project_plan(p_plan_id UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public SET row_security = off AS $$
  WITH me AS (SELECT id FROM public.users WHERE auth_user_id = auth.uid() AND is_deleted = FALSE LIMIT 1)
  SELECT EXISTS (
    SELECT 1 FROM public.project_plans pl
    WHERE pl.id = p_plan_id AND pl.is_deleted = FALSE AND pl.is_baseline = FALSE
      AND (
        EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.roles r ON ur.role_id = r.id JOIN public.users u ON ur.user_id = u.id
                WHERE u.auth_user_id = auth.uid() AND r.role_name IN ('pmo_admin', 'System Admin')
                  AND ur.is_active = TRUE AND ur.is_deleted = FALSE)
        OR (
          pl.status IN ('draft', 'under_review')
          AND (pl.author_id = (SELECT id FROM me) OR pl.owner_id = (SELECT id FROM me) OR pl.created_by = (SELECT id FROM me))
          AND EXISTS (SELECT 1 FROM public.user_projects up JOIN public.users u ON up.user_id = u.id
                      WHERE u.auth_user_id = auth.uid() AND up.project_id = pl.project_id
                        AND up.access_level IN ('owner', 'admin') AND up.is_deleted = FALSE)
        )
      )
  )
$$;
GRANT EXECUTE ON FUNCTION public.auth_user_can_view_project_plan(UUID), public.auth_user_can_edit_project_plan(UUID) TO authenticated;

