GRANT EXECUTE ON FUNCTION public.auth_user_can_view_stage_plan(UUID), public.auth_user_can_edit_stage_plan(UUID) TO authenticated;

-- project_plan_key_risks: project plan key risks (Risk | Impact | Owner | Response).
CREATE TABLE IF NOT EXISTS public.project_plan_key_risks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  project_plan_id UUID NOT NULL REFERENCES public.project_plans(id) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  risk_title TEXT,
  impact TEXT,
  owner TEXT,
  response TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_project_plan_key_risks_parent ON public.project_plan_key_risks (project_plan_id, sort_order);
ALTER TABLE public.project_plan_key_risks ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.project_plan_key_risks TO authenticated;
DROP POLICY IF EXISTS project_plan_key_risks_select ON public.project_plan_key_risks;
CREATE POLICY project_plan_key_risks_select ON public.project_plan_key_risks FOR SELECT TO authenticated USING (public.auth_user_can_view_project_plan(project_plan_id));
DROP POLICY IF EXISTS project_plan_key_risks_insert ON public.project_plan_key_risks;
CREATE POLICY project_plan_key_risks_insert ON public.project_plan_key_risks FOR INSERT TO authenticated WITH CHECK (public.auth_user_can_edit_project_plan(project_plan_id));
DROP POLICY IF EXISTS project_plan_key_risks_update ON public.project_plan_key_risks;
CREATE POLICY project_plan_key_risks_update ON public.project_plan_key_risks FOR UPDATE TO authenticated USING (public.auth_user_can_edit_project_plan(project_plan_id)) WITH CHECK (public.auth_user_can_edit_project_plan(project_plan_id));
DROP POLICY IF EXISTS project_plan_key_risks_delete ON public.project_plan_key_risks;
CREATE POLICY project_plan_key_risks_delete ON public.project_plan_key_risks FOR DELETE TO authenticated USING (public.auth_user_can_edit_project_plan(project_plan_id));
INSERT INTO public.project_plan_key_risks (project_plan_id, sort_order, risk_title, impact, owner, response)
SELECT e.plan_id, e.ord, COALESCE(e.map_key, public.plan_list_pick(e.val, ARRAY['risk_title', 'risk', 'title', 'name', 'description']), CASE WHEN e.map_key IS NULL THEN public.plan_list_scalar(e.val) END),
       COALESCE(public.plan_list_pick(e.val, ARRAY['impact', 'rating', 'severity']), CASE WHEN e.map_key IS NOT NULL THEN public.plan_list_scalar(e.val) END),
       public.plan_list_pick(e.val, ARRAY['owner', 'risk_owner']),
       public.plan_list_pick(e.val, ARRAY['response', 'mitigation', 'action'])
FROM (
  SELECT pl.id AS plan_id, a.ord::INTEGER AS ord, NULL::TEXT AS map_key, a.val
  FROM public.project_plans pl CROSS JOIN LATERAL jsonb_array_elements(pl.key_risks) WITH ORDINALITY AS a(val, ord)
  WHERE jsonb_typeof(pl.key_risks) = 'array'
  UNION ALL
  SELECT pl.id, o.ord::INTEGER, o.k, o.val
  FROM public.project_plans pl CROSS JOIN LATERAL jsonb_each(pl.key_risks) WITH ORDINALITY AS o(k, val, ord)
  WHERE jsonb_typeof(pl.key_risks) = 'object'
) e
WHERE e.val IS NOT NULL AND e.val NOT IN ('{}'::jsonb, 'null'::jsonb, '""'::jsonb)
  AND NOT EXISTS (SELECT 1 FROM public.project_plan_key_risks x WHERE x.project_plan_id = e.plan_id);
COMMENT ON COLUMN public.project_plans.key_risks IS 'Superseded by public.project_plan_key_risks (v1542). Kept for reference; no longer written by the app.';

