  category TEXT,
  amount NUMERIC(18,2),
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_stage_plan_budget_lines_parent ON public.stage_plan_budget_lines (stage_plan_id, sort_order);
ALTER TABLE public.stage_plan_budget_lines ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.stage_plan_budget_lines TO authenticated;
DROP POLICY IF EXISTS stage_plan_budget_lines_select ON public.stage_plan_budget_lines;
CREATE POLICY stage_plan_budget_lines_select ON public.stage_plan_budget_lines FOR SELECT TO authenticated USING (public.auth_user_can_view_stage_plan(stage_plan_id));
DROP POLICY IF EXISTS stage_plan_budget_lines_insert ON public.stage_plan_budget_lines;
CREATE POLICY stage_plan_budget_lines_insert ON public.stage_plan_budget_lines FOR INSERT TO authenticated WITH CHECK (public.auth_user_can_edit_stage_plan(stage_plan_id));
DROP POLICY IF EXISTS stage_plan_budget_lines_update ON public.stage_plan_budget_lines;
CREATE POLICY stage_plan_budget_lines_update ON public.stage_plan_budget_lines FOR UPDATE TO authenticated USING (public.auth_user_can_edit_stage_plan(stage_plan_id)) WITH CHECK (public.auth_user_can_edit_stage_plan(stage_plan_id));
DROP POLICY IF EXISTS stage_plan_budget_lines_delete ON public.stage_plan_budget_lines;
CREATE POLICY stage_plan_budget_lines_delete ON public.stage_plan_budget_lines FOR DELETE TO authenticated USING (public.auth_user_can_edit_stage_plan(stage_plan_id));
INSERT INTO public.stage_plan_budget_lines (stage_plan_id, sort_order, category, amount, notes)
SELECT e.plan_id, e.ord, COALESCE(e.map_key, public.plan_list_pick(e.val, ARRAY['category', 'name', 'item', 'stage', 'work_package']), CASE WHEN e.map_key IS NULL THEN public.plan_list_scalar(e.val) END),
       public.plan_list_numeric(COALESCE(public.plan_list_pick(e.val, ARRAY['amount', 'value', 'budget', 'cost']), CASE WHEN e.map_key IS NOT NULL THEN public.plan_list_scalar(e.val) END)),
       public.plan_list_pick(e.val, ARRAY['notes', 'description'])
FROM (
  SELECT pl.id AS plan_id, a.ord::INTEGER AS ord, NULL::TEXT AS map_key, a.val
  FROM public.stage_plans pl CROSS JOIN LATERAL jsonb_array_elements(pl.budget_breakdown) WITH ORDINALITY AS a(val, ord)
  WHERE jsonb_typeof(pl.budget_breakdown) = 'array'
  UNION ALL
  SELECT pl.id, o.ord::INTEGER, o.k, o.val
  FROM public.stage_plans pl CROSS JOIN LATERAL jsonb_each(pl.budget_breakdown) WITH ORDINALITY AS o(k, val, ord)
  WHERE jsonb_typeof(pl.budget_breakdown) = 'object'
) e
WHERE e.val IS NOT NULL AND e.val NOT IN ('{}'::jsonb, 'null'::jsonb, '""'::jsonb)
  AND NOT EXISTS (SELECT 1 FROM public.stage_plan_budget_lines x WHERE x.stage_plan_id = e.plan_id);
COMMENT ON COLUMN public.stage_plans.budget_breakdown IS 'Superseded by public.stage_plan_budget_lines (v1542). Kept for reference; no longer written by the app.';

